      <!-- contact Form section start -->
      <section class="contact-six v4 section section-padding">
        <div class="container">
          <div class="row">
            <div class="col-12">
              <div class="patisserie__header text-center fade-anim">
                <h2 class="header-title mx-auto">
                  <span class="line-text position-relative">
                    <span class="top-tag v2">Contact</span>
                    We’d love to hear
                  </span>
                  <br />
                  <span class="line-text position-relative">
                    from you
                    <span class="bottom-tag v4">food delivery</span>
                  </span>
                </h2>
              </div>
            </div>
          </div>
          <div class="row row-padding-top">
            <form action="#" class="contact-six__form">
              <div class="row g-4">
                <div class="col-md-6">
                  <div class="form-group">
                    <label for="fullName">Full Name *</label>
                    <div class="input-wrap">
                      <input
                        type="text"
                        id="fullName"
                        class="form-control"
                        placeholder="Wade"
                      />
                      <i class="fa-light fa-circle-user"></i>
                    </div>
                  </div>
                </div>
                <div class="col-md-6">
                  <div class="form-group">
                    <label for="emailAddress">Email *</label>
                    <div class="input-wrap">
                      <input
                        type="email"
                        id="emailAddress"
                        class="form-control"
                        placeholder="info@dinevo"
                      />
                      <i class="fa-light fa-envelope"></i>
                    </div>
                  </div>
                </div>
                <div class="col-md-6">
                  <div class="form-group">
                    <label for="phoneNumber">Phone Number *</label>
                    <div class="input-wrap">
                      <input
                        type="tel"
                        id="phoneNumber"
                        class="form-control"
                        placeholder="+1 (555) 123-4567"
                      />
                      <i class="fa-light fa-phone"></i>
                    </div>
                  </div>
                </div>
                <div class="col-md-6">
                  <div class="form-group">
                    <label for="subject">Subject *</label>
                    <div class="input-wrap">
                      <select id="subject" class="form-control form-select">
                        <option value="coffee" selected>Coffee</option>
                        <option value="food">Food</option>
                        <option value="other">Other</option>
                      </select>
                    </div>
                  </div>
                </div>
                <div class="col-12">
                  <div class="form-group">
                    <label for="message">Message *</label>
                    <div class="input-wrap">
                      <textarea
                        id="message"
                        class="form-control"
                        placeholder="Write your text..."
                      ></textarea>
                      <i class="fa-solid fa-pen-fancy"></i>
                    </div>
                  </div>
                </div>
                <div class="col-12">
                  <div class="form-group text-center">
                    <button type="submit" class="common-button-five v2">
                      <span class="btn-text">Submit Now</span>
                    </button>
                  </div>
                </div>
              </div>
            </form>
          </div>
        </div>
      </section>
      <!-- contact Form section end -->
    
